import { readSnapshot } from './sources.js';
 import { MAX_SNAPSHOT_AGE_MS } from './policy.js';
 import { SnapshotFailure } from './errors.js';
 export function usableSnapshot(now: number) {
   const snapshot = readSnapshot();
   if (now - snapshot.savedAt > MAX_SNAPSHOT_AGE_MS) {
     throw new SnapshotFailure('CACHE_TOO_OLD');
   }
   return { uri: snapshot.uri };
 }

