import { fetchCurrent } from './sources.js';
 import { usableSnapshot } from './snapshot.js';
 import { RemoteFailure } from './errors.js';
 export async function loadThumbnail(now: number) {
   try { return await fetchCurrent(); }
   catch (error) {
     if (error instanceof RemoteFailure) return usableSnapshot(now);
     throw error;
   }
 }

