import { SnapshotFailure } from './errors.js';
 export function failureResponse(error: unknown) {
   if (error instanceof SnapshotFailure && error.reason === 'CACHE_TOO_OLD') {
     return { status: 409, code: 'THUMBNAIL_SOURCE_STALE' };
   }
   return { status: 503, code: 'THUMBNAIL_UNAVAILABLE' };
 }

