import { loadThumbnail } from './loader.js';
 import { failureResponse } from './responses.js';
 import { REQUEST_TIME_MS } from './policy.js';
 export async function handleThumbnail() {
   try { return { status: 200, code: 'THUMBNAIL_READY', ...await loadThumbnail(REQUEST_TIME_MS) }; }
   catch (error) { return failureResponse(error); }
 }
